const repo = "acme/cli";
const start = Date.now();
const byNum = new Map<number, any>();
let paginationStopped = "max pages";

for (let page = 1; page <= 30; page++) {
  const r: any = await tools.list_issues({ repo, state: "open", page });
  const items: any[] = Array.isArray(r) ? r : (r?.items ?? r?.issues ?? []);
  if (!items.length) { paginationStopped = "empty page"; break; }
  let added = 0;
  for (const it of items) {
    if (it?.number != null && !byNum.has(it.number)) {
      byNum.set(it.number, it);
      added++;
    }
  }
  if (added === 0) { paginationStopped = "no new items"; break; }
  if (Date.now() - start > 8000) { paginationStopped = "time guard"; break; }
}

const nums = [...byNum.keys()];
const missingLabels = nums.filter(n => !Array.isArray(byNum.get(n)?.labels));

const fetched = await Promise.all(
  missingLabels.map(n =>
    tools.get_issue({ repo, number: n })
      .then((i: any) => [n, i] as const)
      .catch((e: any) => [n, { error: String(e?.message ?? e) }] as const)
  )
);
for (const [n, i] of fetched) {
  if (i && Array.isArray((i as any).labels)) byNum.set(n, i);
  else byNum.set(n, { ...(byNum.get(n) ?? {}), _error: (i as any)?.error ?? "no labels field" });
}

const unlabeled: number[] = [];
const skipped: any[] = [];
for (const n of nums) {
  const it = byNum.get(n);
  if (!Array.isArray(it?.labels)) { skipped.push({ number: n, reason: it?._error ?? "no labels" }); continue; }
  if (it.state && it.state !== "open") { skipped.push({ number: n, reason: "not open" }); continue; }
  if (it.labels.length === 0) unlabeled.push(n);
}

const results = await Promise.all(
  unlabeled.map(n =>
    tools.add_label({ repo, number: n, label: "needs-triage" })
      .then(() => ({ number: n, ok: true }))
      .catch((e: any) => ({ number: n, ok: false, error: String(e?.message ?? e) }))
  )
);

return {
  paginationStopped,
  openCount: nums.length,
  unlabeled,
  skipped,
  results,
  elapsedMs: Date.now() - start,
};
